'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {RippleNeuron}=require('../src/ripple_core_reference');
const fb=require('../src/feedback_sweep');const math=require('../src/specialist_math');const {SpecialistColony,workloads,service}=require('../src/specialist_colony');
const source=path.resolve(__dirname,'../src/ripple_core_reference.js'),baseline=path.resolve(__dirname,'../baseline_v0.2/ripple_core_reference.js');
test('original neuron kernel byte-identical to v0.2',()=>assert.deepEqual(fs.readFileSync(source),fs.readFileSync(baseline)));
test('feasible target inverse equation at D=.7',()=>assert.ok(Math.abs(fb.feasibleTheta(.7,1)-.584285)<1e-4));
test('infeasible target rejected',()=>{for(const x of [-1,0,10,12])assert.equal(fb.feasibleTheta(.7,x),null);});
test('frequency inverse at three drives',()=>{for(let d of [.4,.7,1.4]){let theta=fb.feasibleTheta(d,1);assert.ok(Math.abs(fb.analyticFrequency(d,theta)-1)<1e-12);}});
test('no spontaneous pulses during darkness',()=>{for(let m of fb.methods){const n=new fb.ControlledNeuron(m);for(let i=0;i<1200;i++)assert.equal(n.step([0,0,0],.05).count,0);}});
test('inhibition stops excitation in steady state',()=>{for(let m of ['original','hybrid-fast']){const n=new fb.ControlledNeuron(m);for(let i=0;i<60;i++)n.step([.5,0,0],.05);let count=0;for(let i=0;i<400;i++)count+=n.step([.4,0,1],.05).count;assert.equal(count,0);}});
test('unmodified original vs controlled original exact state',()=>{const a=new RippleNeuron(),b=new fb.ControlledNeuron('original');for(let i=0;i<1000;i++){const x=[.2+(i%20)/100,.1,.05],a1=a.step(x,.05),b1=b.step(x,.05);assert.deepEqual(b1,a1);}});
test('analytic fixed theta matches long-run deterministic firing',()=>{const d=.7,theta=.52,n=new RippleNeuron({theta,adaptive:false});let events=0;for(let i=0;i<20000;i++)events+=n.step([d/2,0,0],.05).count;assert.ok(Math.abs(events/1000-fb.analyticFrequency(d,theta))<.003);});
test('hybrid improves tracking vs original on steady drive',()=>{const orig=fb.evaluate('original','constant-mid',1),hybrid=fb.evaluate('hybrid-fast','constant-mid',1);assert.ok(hybrid.mae<orig.mae);});
test('integral candidate can be worse and stays an experimental negative control',()=>{const r=fb.evaluate('rate-PI','step-down',1);assert.ok(Number.isFinite(r.mae));});
test('product values add exactly across arbitrary partitions',()=>{const all=math.makeProduct(3,100);let exp=math.productStats(all),partials=[all.slice(0,33),all.slice(33,71),all.slice(71)].map(math.productStats);
 for(let key of ['revenue','cost','quantity','shortfall'])assert.equal(partials.reduce((a,x)=>a+x[key],0),exp[key]);});
test('invalid product data rejected',()=>assert.throws(()=>math.productStats([{quantity:-1,unitPriceCents:3,unitCostCents:1,stock:0}])));
test('study detects duplication across worker partitions',()=>{const a={id:'x',value:2,variance:1},b={id:'y',value:4,variance:1},r=math.studyCombine([[a],[b,a]]);assert.equal(r.duplicateEvidence,1);assert.equal(r.n,2);assert.equal(r.mean,3);});
test('study correct independent inverse-variance precision',()=>{const r=math.studyCombine([[{id:'A',value:2,variance:1},{id:'B',value:4,variance:4}]]);assert.ok(Math.abs(r.mean-2.4)<1e-12);assert.ok(Math.abs(r.se-Math.sqrt(.8))<1e-12);});
test('study disagreement flag is explicit heuristic',()=>{const r=math.studyCombine([[{id:'A',value:-15,variance:.1},{id:'B',value:15,variance:.1}]]);assert.equal(r.possibleConflict,true);});
test('gradient checked by independent finite differences',()=>{const w=[.2,.4,-.3],examples=math.makeLearning(20),r=math.lossGradient(examples,w),eps=1e-5;for(let k=0;k<3;k++){
 let left=[...w],right=[...w];left[k]-=eps;right[k]+=eps;let approx=(math.lossGradient(examples,right).loss-math.lossGradient(examples,left).loss)/(2*eps);assert.ok(Math.abs(approx-r.gradient[k])<1e-7);
}});
test('specialist speed model is disclosed work-units, not observed hardware',()=>{assert.equal(service('learning','learning'),1);assert.equal(service('general','learning'),2);assert.equal(service('product','study'),3);});
test('clones own independent neuron states',()=>{const c=new SpecialistColony({growth:'fixed4'});c.workers[0].engine.theta=1.17;assert.notEqual(c.workers[0].engine.theta,c.workers[1].engine.theta);});
test('fixed population cap respected and requests accounted',()=>{const c=new SpecialistColony({growth:'capacity-specialist',maxNodes:3});const w=workloads('burst'),out=c.run(230,w);assert.equal(out.completed+out.pending,w.length);assert.ok(out.spawns<=20);assert.ok(out.remaining<=3);});
test('all arithmetic modes run and recombine',()=>{const c=new SpecialistColony({growth:'capacity-specialist'});let arr=workloads('balanced'),out=c.run(230,arr);assert.equal(out.completed,arr.length);assert.equal(out.pending,0);assert.equal(out.byType.learning>0,true);assert.equal(out.byType.product>0,true);assert.equal(out.byType.study>0,true);});
test('genuine out-of-sample learning from synthetic examples',()=>{const train=workloads('learning'),c=new SpecialistColony({growth:'capacity-specialist',route:'affinity'});c.run(230,train);const holdout=math.makeLearning(360).slice(220);
 assert.ok(math.accuracy(holdout,c.weight)>.9);assert.ok(math.accuracy(holdout,c.weight)>math.accuracy(holdout,[0,0,0])+.25);assert.ok(c.trainingTrace.length>30);});
test('all five specialist task profiles deterministic replay',()=>{for(let t of ['balanced','learning','product','study','shift','burst']){const a=new SpecialistColony(),b=new SpecialistColony();const w=workloads(t);assert.deepEqual(a.run(230,w),b.run(230,w));}});
test('work not lost when idle workers retire',()=>{const c=new SpecialistColony({growth:'capacity-specialist'}),arr=workloads('balanced'),result=c.run(230,arr);assert.equal(result.completed,arr.length);assert.ok(result.retirements>0);assert.equal(result.remaining,1);});
test('three topology hop delay distances differ when pool grows',()=>{const results=['tree','ring','mesh'].map(graph=>{let c=new SpecialistColony({growth:'fixed4',graph});return c.distance(c.workers[3].id);});assert.notDeepEqual(results,[1,1,1]);});
